function main(): void {
    const err = new Error("boom");
    const invoke: any = (cb: any): any => cb();
    try {
        try {
            invoke(() => { throw err; });
        } catch (e: any) {
            throw e;
        }
    } catch (outer: any) {
        console.log(outer === err, outer.message);
    }
}
